public class Solution{int[,]s=new int[10,10];bool[]v=new bool[10];int F(int cur,int left){if(left==0)return 1;v[cur]=true;int r=0;for(int x=1;x<=9;x++)if(!v[x]&&(s[cur,x]==0||v[s[cur,x]]))r+=F(x,left-1);v[cur]=false;return r;}public int NumberOfPatterns(int m,int n){int[][]p={new[]{1,3,2},new[]{1,7,4},new[]{3,9,6},new[]{7,9,8},new[]{1,9,5},new[]{3,7,5},new[]{4,6,5},new[]{2,8,5}};foreach(var x in p)s[x[0],x[1]]=s[x[1],x[0]]=x[2];int r=0;for(int l=m;l<=n;l++)r+=4*F(1,l-1)+4*F(2,l-1)+F(5,l-1);return r;}}
